const request = require('request');

const options = {
  method: 'GET',
  url: 'https://api.procore.com/rest/v1.0/companies/%7Bcompany_id%7D/checklist/item/response_sets/%7Bresponse_set_id%7D/responses',
  qs: {'filters[corresponding_status]': 'SOME_ARRAY_VALUE', sort: 'SOME_STRING_VALUE'},
  headers: {Authorization: 'Bearer REPLACE_BEARER_TOKEN'}
};

request(options, function (error, response, body) {
  if (error) throw new Error(error);

  console.log(body);
});

var client = new HttpClient();
var request = new HttpRequestMessage
{
    Method = HttpMethod.Get,
    RequestUri = new Uri("https://api.procore.com/rest/v1.0/companies/%7Bcompany_id%7D/checklist/item/response_sets/%7Bresponse_set_id%7D/responses?filters%5Bcorresponding_status%5D=SOME_ARRAY_VALUE&sort=SOME_STRING_VALUE"),
    Headers =
    {
        { "Authorization", "Bearer REPLACE_BEARER_TOKEN" },
    },
};
using (var response = await client.SendAsync(request))
{
    response.EnsureSuccessStatusCode();
    var body = await response.Content.ReadAsStringAsync();
    Console.WriteLine(body);
}

